  "cmdServe": {
    file: "cmd/todo/main.go",
    startLine: 199,
    code: "func cmdServe(args []string, e env) int {\n\tfs := flag.NewFlagSet(\"serve\", flag.ContinueOnError)\n\tfs.SetOutput(e.stderr)\n\tfile := fs.String(\"file\", defaultPath(), \"todo JSON file\")\n\taddr := fs.String(\"addr\", \":8080\", \"listen address\")\n\tdev := fs.Bool(\"dev\", false, \"enable CORS for local Vite and skip the embedded UI\")\n\tfs.Usage = func() {\n\t\tfmt.Fprintln(e.stderr, \"usage: todo serve [-file path] [-addr :8080] [-dev]\")\n\t}\n\tif err := fs.Parse(args); err != nil {\n\t\treturn 2\n\t}\n\tif fs.NArg() != 0 {\n\t\tfs.Usage()\n\t\treturn 2\n\t}\n\tlogger := log.New(e.stderr, \"\", log.LstdFlags)\n\tsrv := api.New(store.NewJSONFile(*file), api.Options{Dev: *dev, Logger: logger})\n\tvar handler http.Handler = srv.Handler()\n\tif !*dev {\n\t\tfiles, err := web.Dist()\n\t\tif err != nil {\n\t\t\tfmt.Fprintln(e.stderr, err)\n\t\t\treturn 1\n\t\t}\n\t\thandler = api.WithStatic(handler, files)\n\t}\n\thttpServer := &http.Server{\n\t\tAddr:              *addr,\n\t\tHandler:           handler,\n\t\tReadHeaderTimeout: 5 * time.Second,\n\t\tReadTimeout:       15 * time.Second,\n\t\tWriteTimeout:      30 * time.Second,\n\t\tIdleTimeout:       60 * time.Second,\n\t}\n\t// LEARN(context): NotifyContext is canceled when the process receives Ctrl-C or SIGTERM. Remind and Shutdown both stop because of that cancellation.\n\tctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)\n\tdefer stop()\n\t// LEARN(goroutines): go starts Remind at the same time as the HTTP server. Requests keep flowing while the ticker loop watches for overdue tasks.\n\tgo srv.Remind(ctx, time.Minute)\n\tfmt.Fprintf(e.stdout, \"serving %s (file %s)\\n\", *addr, *file)\n\terrCh := make(chan error, 1)\n\tgo func() {\n\t\terrCh <- httpServer.ListenAndServe()\n\t}()\n\tselect {\n\tcase <-ctx.Done():\n\t\tshut, cancel := context.WithTimeout(context.Background(), 5*time.Second)\n\t\tdefer cancel()\n\t\tif err := httpServer.Shutdown(shut); err != nil {\n\t\t\tfmt.Fprintln(e.stderr, err)\n\t\t\treturn 1\n\t\t}\n\t\treturn 0\n\tcase err := <-errCh:\n\t\tif errors.Is(err, http.ErrServerClosed) {\n\t\t\treturn 0\n\t\t}\n\t\tfmt.Fprintln(e.stderr, err)\n\t\treturn 1\n\t}\n}",
  },
  "collect": {
    file: "scripts/gen-go-sources.go",
    startLine: 86,
    code: "func collect(root string) (map[string]snippet, error) {\n\t// LEARN(go-ast): parser.ParseFile turns a .go file into an ast.File, a tree of declarations. We walk each FuncDecl, then slice the original source from the function's start line to its end line. The React app shows that slice when a response names the function.\n\tdirs := []string{\n\t\tfilepath.Join(root, \"cmd\"),\n\t\tfilepath.Join(root, \"internal\"),\n\t\tfilepath.Join(root, \"scripts\"),\n\t\tfilepath.Join(root, \"web\"),\n\t}\n\tvar files []string\n\tfor _, dir := range dirs {\n\t\terr := filepath.WalkDir(dir, func(path string, d os.DirEntry, err error) error {\n\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\tif d.IsDir() {\n\t\t\t\tswitch d.Name() {\n\t\t\t\tcase \"node_modules\", \"dist\":\n\t\t\t\t\treturn filepath.SkipDir\n\t\t\t\t}\n\t\t\t\treturn nil\n\t\t\t}\n\t\t\tif strings.HasSuffix(path, \".go\") {\n\t\t\t\tfiles = append(files, path)\n\t\t\t}\n\t\t\treturn nil\n\t\t})\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t}\n\tsort.Strings(files)\n\n\ttype item struct {\n\t\tname  string\n\t\tfile  string\n\t\trecv  string\n\t\tpkg   string\n\t\tstart int\n\t\tcode  string\n\t}\n\tvar items []item\n\tfor _, path := range files {\n\t\tfset := token.NewFileSet()\n\t\tfile, err := parser.ParseFile(fset, path, nil, parser.ParseComments)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\trel, err := filepath.Rel(root, path)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\trel = filepath.ToSlash(rel)\n\t\tsrc, err := os.ReadFile(path)\n\t\tif err != nil {\n\t\t\treturn nil, err\n\t\t}\n\t\tlines := strings.Split(string(src), \"\\n\")\n\t\tfor _, decl := range file.Decls {\n\t\t\tfn, ok := decl.(*ast.FuncDecl)\n\t\t\tif !ok || fn.Body == nil {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\tstartTok := fn.Pos()\n\t\t\tif fn.Doc != nil {\n\t\t\t\tstartTok = fn.Doc.Pos()\n\t\t\t}\n\t\t\tstart := fset.Position(startTok).Line\n\t\t\tend := fset.Position(fn.End()).Line\n\t\t\tif start < 1 || end > len(lines) || end < start {\n\t\t\t\tcontinue\n\t\t\t}\n\t\t\trecv := \"\"\n\t\t\tif fn.Recv != nil && len(fn.Recv.List) > 0 {\n\t\t\t\trecv = typeName(fn.Recv.List[0].Type)\n\t\t\t}\n\t\t\titems = append(items, item{\n\t\t\t\tname:  fn.Name.Name,\n\t\t\t\tfile:  rel,\n\t\t\t\trecv:  recv,\n\t\t\t\tpkg:   file.Name.Name,\n\t\t\t\tstart: start,\n\t\t\t\tcode:  strings.Join(lines[start-1:end], \"\\n\"),\n\t\t\t})\n\t\t}\n\t}\n\n\tcounts := map[string]int{}\n\tfor _, it := range items {\n\t\tcounts[it.name]++\n\t}\n\tout := map[string]snippet{}\n\tfor _, it := range items {\n\t\tkey := it.name\n\t\tif it.recv == \"List\" {\n\t\t\tkey = \"List.\" + it.name\n\t\t} else if counts[it.name] > 1 {\n\t\t\tif it.recv != \"\" {\n\t\t\t\tkey = it.recv + \".\" + it.name\n\t\t\t} else {\n\t\t\t\tkey = it.pkg + \".\" + it.name\n\t\t\t}\n\t\t}\n\t\tif _, exists := out[key]; exists {\n\t\t\tkey = it.pkg + \".\" + it.file + \".\" + it.name\n\t\t}\n\t\tout[key] = snippet{file: it.file, start: it.start, code: it.code}\n\t}\n\treturn out, nil\n}",
  },
