    code: "func handlerConcepts(path string) (map[string][]string, error) {\n\tdata, err := os.ReadFile(path)\n\tif err != nil {\n\t\treturn nil, err\n\t}\n\tblock := regexp.MustCompile(`(?s)\"([A-Za-z0-9]+)\"\\s*:\\s*\\{(.*?)\\}`)\n\tid := regexp.MustCompile(`\"([a-z0-9-]+)\"`)\n\tout := map[string][]string{}\n\tfor _, m := range block.FindAllStringSubmatch(string(data), -1) {\n\t\tvar ids []string\n\t\tfor _, im := range id.FindAllStringSubmatch(m[2], -1) {\n\t\t\tids = append(ids, im[1])\n\t\t}\n\t\tout[m[1]] = ids\n\t}\n\tif len(out) == 0 {\n\t\treturn nil, fmt.Errorf(\"no HandlerConcepts entries in %s\", path)\n\t}\n\treturn out, nil\n}",
