    code: "func main() {\n\troot, err := moduleRoot()\n\tif err != nil {\n\t\tfatal(err)\n\t}\n\tsnippets, err := collect(root)\n\tif err != nil {\n\t\tfatal(err)\n\t}\n\tconcepts, err := handlerConcepts(filepath.Join(root, \"internal\", \"learn\", \"trace.go\"))\n\tif err != nil {\n\t\tfatal(err)\n\t}\n\tvar buf bytes.Buffer\n\tbuf.WriteString(\"// Generated by scripts/gen-go-sources.go. Do not edit by hand.\\n\")\n\tbuf.WriteString(\"// Run `make gen` after changing Go sources.\\n\\n\")\n\tbuf.WriteString(\"export type GoSource = {\\n\")\n\tbuf.WriteString(\"  file: string;\\n\")\n\tbuf.WriteString(\"  startLine: number;\\n\")\n\tbuf.WriteString(\"  code: string;\\n\")\n\tbuf.WriteString(\"};\\n\\n\")\n\tbuf.WriteString(\"export const goSources: Record<string, GoSource> = {\\n\")\n\tkeys := make([]string, 0, len(snippets))\n\tfor k := range snippets {\n\t\tkeys = append(keys, k)\n\t}\n\tsort.Strings(keys)\n\tfor _, key := range keys {\n\t\tsn := snippets[key]\n\t\tbuf.WriteString(\"  \" + strconv.Quote(key) + \": {\\n\")\n\t\tbuf.WriteString(\"    file: \" + strconv.Quote(sn.file) + \",\\n\")\n\t\tbuf.WriteString(\"    startLine: \" + strconv.Itoa(sn.start) + \",\\n\")\n\t\tbuf.WriteString(\"    code: \" + strconv.Quote(sn.code) + \",\\n\")\n\t\tbuf.WriteString(\"  },\\n\")\n\t}\n\tbuf.WriteString(\"};\\n\\n\")\n\tbuf.WriteString(\"export const handlerConcepts: Record<string, string[]> = {\\n\")\n\thkeys := make([]string, 0, len(concepts))\n\tfor k := range concepts {\n\t\thkeys = append(hkeys, k)\n\t}\n\tsort.Strings(hkeys)\n\tfor _, key := range hkeys {\n\t\tids := make([]string, len(concepts[key]))\n\t\tfor i, id := range concepts[key] {\n\t\t\tids[i] = strconv.Quote(id)\n\t\t}\n\t\tbuf.WriteString(\"  \" + strconv.Quote(key) + \": [\" + strings.Join(ids, \", \") + \"],\\n\")\n\t}\n\tbuf.WriteString(\"};\\n\")\n\n\tout := filepath.Join(root, \"web\", \"src\", \"learn\", \"goSources.ts\")\n\tif err := os.MkdirAll(filepath.Dir(out), 0o755); err != nil {\n\t\tfatal(err)\n\t}\n\tif err := os.WriteFile(out, buf.Bytes(), 0o644); err != nil {\n\t\tfatal(err)\n\t}\n\tfmt.Fprintf(os.Stderr, \"wrote %s (%d snippets)\\n\", out, len(snippets))\n}",
